func (q *Queries) UpdateCompanySettings(ctx context.Context, arg UpdateCompanySettingsParams) (Company, error) {
	row := q.db.QueryRow(ctx, updateCompanySettings,
		arg.Name,
		arg.LegalName,
		arg.Phone,
		arg.Email,
		arg.LogoUrl,
		arg.BookingHoldMinutes,
		arg.SalesCutoffMinutes,
		arg.CancellationCutoffHours,
		arg.CancellationFeePercent,
		arg.RefundApprovalThreshold,
		arg.ChangeEnabled,
		arg.ChangeCutoffHours,
		arg.ChangeFeeAmount,
		arg.ChangeMaxCount,
		arg.ChangeWindowDays,
		arg.BaggageExtraPerKg,
		arg.TaxID,
		arg.TradeRegister,
		arg.Address,
		arg.InvoicePrefix,
		arg.InvoiceFooter,
		arg.PayLaterEnabled,
		arg.PayLaterHoldHours,
		arg.PayLaterCutoffMinutes,
		arg.PayLaterMaxSeats,
		arg.PayLaterMaxActive,
		arg.PayLaterQuotaPercent,
		arg.PayLaterStrikes,
		arg.ID,
	)
	var i Company
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.LegalName,
		&i.Phone,
		&i.Email,
		&i.LogoUrl,
		&i.Currency,
		&i.Timezone,
		&i.BookingHoldMinutes,
		&i.SalesCutoffMinutes,
		&i.CancellationCutoffHours,
		&i.CancellationFeePercent,
		&i.RefundApprovalThreshold,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ChangeEnabled,
		&i.ChangeCutoffHours,
		&i.ChangeFeeAmount,
		&i.ChangeMaxCount,
		&i.ChangeWindowDays,
		&i.BaggageExtraPerKg,
		&i.TaxID,
		&i.TradeRegister,
		&i.Address,
		&i.InvoicePrefix,
		&i.InvoiceFooter,
		&i.PayLaterEnabled,
		&i.PayLaterHoldHours,
		&i.PayLaterCutoffMinutes,
		&i.PayLaterMaxSeats,
		&i.PayLaterMaxActive,
		&i.PayLaterQuotaPercent,
		&i.PayLaterStrikes,
	)
	return i, err
}
